<script setup>
import { ref } from 'vue';
import { api } from '../../services/api.js';
import { notify } from '../../services/notifications.js';
import AuthCard from '../../components/AuthCard.vue';
import Icon from '../../components/Icon.vue';
const email=ref(''), name=ref(''), loading=ref(false),sent=ref(false),error=ref('');
async function submit(){if(loading.value)return;loading.value=true;error.value='';try{await api.post('/auth/magic/request',{email:email.value.trim(),name:name.value.trim()});sent.value=true;notify.success('Revisá tu correo para continuar.');}catch(e){error.value=e.message;}finally{loading.value=false;}}
</script>
<template><AuthCard :title="sent?'Revisá tu correo':'Bienvenido a tu próximo paso.'" :subtitle="sent?'Te enviamos un enlace para ingresar. Por seguridad, tiene una duración limitada y se puede usar una sola vez.':'Ingresá tu email y te enviamos un enlace seguro. Si es tu primera vez, creamos tu cuenta automáticamente.'"><div v-if="sent" class="stack"><div class="mail-success"><Icon name="mail" :size="32" /><strong>{{email}}</strong><p>Buscá el mensaje de MiTiendaYa. Si no lo encontrás, revisá la carpeta de spam.</p></div><button class="btn btn-secondary btn-block" @click="sent=false">Usar otro correo o pedir otro enlace</button></div><form v-else @submit.prevent="submit" class="stack"><div v-if="error" role="alert" class="notice error">{{error}}</div><div class="field"><label for="login-name">Tu nombre <span class="muted">(opcional)</span></label><input id="login-name" v-model="name" autocomplete="given-name" maxlength="100" placeholder="¿Cómo te llamás?" /></div><div class="field"><label for="login-email">Correo electrónico</label><input id="login-email" v-model="email" type="email" autocomplete="email" required maxlength="254" placeholder="vos@ejemplo.com" /></div><button class="btn btn-primary btn-block" :disabled="loading"><span v-if="loading" class="spinner"></span>{{loading?'Enviando enlace…':'Enviar enlace para ingresar'}}<Icon v-if="!loading" name="arrow-right" :size="17" /></button><p class="login-safety"><Icon name="shield" :size="15" /> Sin contraseñas para recordar. Tu acceso está en tu correo.</p></form></AuthCard></template>
<style scoped>.mail-success{text-align:center;background:#f2f7ee;padding:25px;border-radius:14px;color:#00796b}.mail-success svg{margin:0 auto 14px}.mail-success strong{display:block;font-size:.9rem;overflow-wrap:anywhere}.mail-success p{font-size:.79rem;margin:14px 0 0;color:#7c8f72}.login-safety{display:flex;align-items:flex-start;gap:9px;font-size:.7rem;color:var(--muted);line-height:1.7;margin:0}.login-safety svg{margin-top:4px}</style>
